export const legacyMessage2775 = defineMessage({ id: "Стены гаснут, пока герой во дворе. Гарнизон ушёл наружу не по своей воле: двор камера прячет за стеной. Пока во дворе было пусто, это ничего не стоило — прятать было некого. Жильцы вопрос вернули, и замер показал, что он больше, чем казался: стена в две клетки при камере в 30° прячет за собой около четырёх с половиной клеток земли, и по ста двадцати сидам на четверти двора герой скрыт целиком, ещё на трети — наполовину. Прятался не только жилец, но и сам герой. Поэтому материал замка уходит в прозрачность 0,45, как только герой вошёл во двор, и возвращается, когда тот вышел. Тень стена кладёт прежнюю: она не исчезла, её видно насквозь.", message: "Стены гаснут, пока герой во дворе. Гарнизон ушёл наружу не по своей воле: двор камера прячет за стеной. Пока во дворе было пусто, это ничего не стоило — прятать было некого. Жильцы вопрос вернули, и замер показал, что он больше, чем казался: стена в две клетки при камере в 30° прячет за собой около четырёх с половиной клеток земли, и по ста двадцати сидам на четверти двора герой скрыт целиком, ещё на трети — наполовину. Прятался не только жилец, но и сам герой. Поэтому материал замка уходит в прозрачность 0,45, как только герой вошёл во двор, и возвращается, когда тот вышел. Тень стена кладёт прежнюю: она не исчезла, её видно насквозь." });
